from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + skill[i]

        S = 0
        for j in range(m - 1):
            mj = mana[j]
            mj1 = mana[j + 1]
            best = 0
            for i in range(n):
                diff = prefix[i + 1] * mj - prefix[i] * mj1
                if diff > best:
                    best = diff
            S += best

        return S + prefix[n] * mana[-1]
